import base64,zlib,json,pathlib,importlib,sys,satquery,hashlib
updates=json.loads(zlib.decompress(base64.b64decode('')))
folder=pathlib.Path(satquery.__file__).parent
for name,source in updates.items():
    (folder/(name+'.py')).write_text(source)
    assert (folder/(name+'.py')).read_text()==source
importlib.invalidate_caches()
for name in updates:
    module='satquery.'+name
    if module in sys.modules: importlib.reload(sys.modules[module])
print('Verified training/evaluation modules installed:',list(updates),flush=True)
